import { stat, unlink } from 'node:fs/promises';
import { isAbsolute, join, dirname } from 'node:path';
import sharp from 'sharp';
import { scheduleCoverArtVariant } from '../image/coverArtVariantScheduler';
import { runVideoProcess, VideoProcessingError } from './videoProcessRunner';

export { VideoProcessingError } from './videoProcessRunner';
export type VideoProcessingProgress = { stage: 'inspect' | 'validate' | 'adapt' | 'cover'; progress: number | null; plan?: 'direct' | 'remux' | 'transcode' };
export interface ProcessedVideoSource {
    plan: 'direct' | 'remux' | 'transcode'; outputPath: string; contentType: 'video/mp4'; byteLength: number;
    durationSeconds: number; width: number; height: number; videoCodec: string; audioCodec: string | null;
    cover?: { path: string; contentType: 'image/jpeg'; source: 'embedded' | 'frame' };
}
type Stream = { index: number; codec_type: string; codec_name: string; codec_tag_string?: string; profile?: string;
    pix_fmt?: string; width?: number; height?: number; channels?: number; disposition?: { attached_pic?: number };
    tags?: Record<string, unknown> };
type Probe = { streams: Stream[]; format: { format_name: string; duration: string; tags?: Record<string, unknown> } };
export type InspectedVideoSource = { probe: Probe; video: Stream; audio: Stream | null; picture: Stream | null;
    durationSeconds: number; videoCompatible: boolean; plan: ProcessedVideoSource['plan'] };
let activeProcesses = 0;
const maximumPixels = 8192 * 4320;
const inputOptions = ['-protocol_whitelist', 'file,pipe', '-format_whitelist', 'mov', '-max_streams', '16'];
const resourceOptions = ['-max_alloc', '268435456', '-max_pixels', String(maximumPixels), '-threads', '2'];
const binary = (name: 'ffmpeg' | 'ffprobe') => process.env[name === 'ffmpeg' ? 'VIDEO_FFMPEG_PATH' : 'VIDEO_FFPROBE_PATH']
    || (process.env.ROOM_AUDIO_FFMPEG_PATH && isAbsolute(process.env.ROOM_AUDIO_FFMPEG_PATH)
        ? join(dirname(process.env.ROOM_AUDIO_FFMPEG_PATH), name) : name);

/** Actual streams decide admission; an attached still is never mistaken for the primary movie. */
export function inspectVideoProbe(value: unknown): InspectedVideoSource {
    const probe = value as Probe;
    if (!probe || !Array.isArray(probe.streams) || probe.streams.length < 1 || probe.streams.length > 16
        || !probe.format || typeof probe.format.format_name !== 'string' || !probe.format.format_name.split(',').includes('mov')) throw new VideoProcessingError('invalid_source');
    if (new Set(probe.streams.map(stream => stream?.index)).size !== probe.streams.length
        || probe.streams.some(stream => !stream || !Number.isInteger(stream.index) || stream.index < 0 || stream.index > 1024
        || typeof stream.codec_type !== 'string' || ['video', 'audio'].includes(stream.codec_type) && typeof stream.codec_name !== 'string')) throw new VideoProcessingError('invalid_source');
    const movies = probe.streams.filter(stream => stream.codec_type === 'video' && stream.disposition?.attached_pic !== 1);
    const audios = probe.streams.filter(stream => stream.codec_type === 'audio');
    if (movies.length !== 1 || audios.length > 1) throw new VideoProcessingError('unsupported_layout');
    const video = movies[0], audio = audios[0] ?? null;
    const durationSeconds = Number(probe.format.duration), width = Number(video.width), height = Number(video.height);
    if (typeof video.width !== 'number' || typeof video.height !== 'number' || !Number.isFinite(durationSeconds) || durationSeconds <= 0 || durationSeconds > 7200 || !Number.isInteger(width)
        || !Number.isInteger(height) || width < 2 || height < 2 || width > 8192 || height > 8192 || width * height > maximumPixels
        || !['h264', 'hevc'].includes(video.codec_name) || audio && (!Number.isInteger(audio.channels) || audio.channels! < 1 || audio.channels! > 8)) throw new VideoProcessingError('unsupported_layout');
    const compliant = video.codec_name === 'h264'
        ? ['yuv420p', 'yuvj420p'].includes(video.pix_fmt ?? '') && ['Constrained Baseline', 'Baseline', 'Main', 'High'].includes(video.profile ?? '')
        : ['Main', 'Main 10'].includes(video.profile ?? '') && ['yuv420p', 'yuv420p10le'].includes(video.pix_fmt ?? '');
    const acceptedAudio = !audio || audio.codec_name === 'aac';
    const picture = probe.streams.find(stream => stream.codec_type === 'video' && stream.disposition?.attached_pic === 1) ?? null;
    // HEVC Main/Main10 in hvc1 MP4 is accepted by policy; MOV and ancillary streams need only remuxing.
    const plainMp4 = probe.format.tags?.major_brand !== 'qt  ' && probe.streams.length === 1 + Number(Boolean(audio))
        && (video.codec_name !== 'hevc' || video.codec_tag_string === 'hvc1')
        && Object.keys(probe.format.tags ?? {}).every(key => ['major_brand', 'minor_version', 'compatible_brands'].includes(key))
        && probe.streams.every(stream => !Object.keys(stream.tags ?? {}).length);
    return { probe, video, audio, picture, durationSeconds, videoCompatible: compliant, plan: !compliant || !acceptedAudio ? 'transcode' : plainMp4 ? 'direct' : 'remux' };
}

/** Parse a bounded probe response without projecting free-form tags or decoder text. */
async function inspect(path: string, signal?: AbortSignal) {
    const text = await runVideoProcess(binary('ffprobe'), ['-v', 'error', ...resourceOptions, ...inputOptions, '-f', 'mov', '-show_streams', '-show_format', '-of', 'json', path], { signal, timeoutMs: 20_000 });
    try { return inspectVideoProbe(JSON.parse(text)); } catch (error) { if (error instanceof VideoProcessingError) throw error; throw new VideoProcessingError('invalid_source'); }
}

/** Decode all selected streams and require the decoder to reach the inspected duration. */
async function decode(path: string, source: InspectedVideoSource, signal?: AbortSignal, onProgress?: (event: VideoProcessingProgress) => void) {
    let finalTime = 0, ended = false;
    const map = ['-map', `0:${source.video.index}`, ...(source.audio ? ['-map', `0:${source.audio.index}`] : [])];
    await runVideoProcess(binary('ffmpeg'), ['-hide_banner', '-nostdin', '-loglevel', 'error', '-nostats', '-xerror', '-max_error_rate', '0',
        '-max_alloc', '268435456', '-max_pixels', String(maximumPixels), '-flags2', '+ignorecrop', '-threads', '2', ...inputOptions,
        '-err_detect', 'crccheck+bitstream+buffer+explode', '-f', 'mov', '-i', path, ...map,
        '-sn', '-dn', '-threads', '2', '-progress', 'pipe:1', '-stats_period', '1', '-f', 'null', '-'], { signal, onLine(line) {
        if (line.startsWith('out_time_us=')) { const number = line.slice(12); if (number === 'N/A') return;
            if (!/^-?\d{1,15}$/.test(number)) throw new VideoProcessingError('invalid_source');
            finalTime = Math.max(finalTime, Number(number) / 1_000_000);
            onProgress?.({ stage: 'validate', progress: Math.min(99, Math.floor(finalTime / source.durationSeconds * 100)) });
        } else if (line === 'progress=end') ended = true;
    } });
    if (!ended || finalTime < source.durationSeconds - .5
        || finalTime > source.durationSeconds + 1) throw new VideoProcessingError('invalid_source');
    onProgress?.({ stage: 'validate', progress: 100 });
}

/** Optional cover failure stays separate from successful media validation. */
async function cover(path: string, source: InspectedVideoSource, directory: string, signal?: AbortSignal): Promise<ProcessedVideoSource['cover']> {
    const raw = join(directory, 'video-cover-raw.jpg'), target = join(directory, 'video-cover.jpg');
    const attempts = source.picture ? ['embedded', 'frame', 'first'] as const : ['frame', 'first'] as const;
    for (const attempt of attempts) {
        signal?.throwIfAborted();
        try {
            const time = attempt === 'frame' ? Math.min(2, source.durationSeconds * .1) : 0;
            await runVideoProcess(binary('ffmpeg'), ['-hide_banner', '-nostdin', '-loglevel', 'error', '-max_alloc', '33554432', '-max_pixels', String(maximumPixels), '-threads', '1', ...inputOptions,
                '-f', 'mov', '-i', path, ...(time ? ['-ss', String(time)] : []), '-map', `0:${attempt === 'embedded' ? source.picture!.index : source.video.index}`,
                '-frames:v', '1', '-an', '-sn', '-dn', '-map_metadata', '-1', '-vf', 'scale=1280:1280:force_original_aspect_ratio=decrease',
                '-threads', '1', '-q:v', '3', '-fs', String(8 * 1024 ** 2), '-y', raw], { signal, timeoutMs: 30_000 });
            await scheduleCoverArtVariant('video-processing', signal, () => sharp(raw, { failOn: 'error', limitInputPixels: 1280 ** 2 })
                .rotate().resize({ width: 1280, height: 1280, fit: 'inside', withoutEnlargement: true }).jpeg({ quality: 88 }).timeout({ seconds: 10 }).toFile(target));
            return { path: target, contentType: 'image/jpeg', source: attempt === 'embedded' ? 'embedded' : 'frame' };
        } catch { signal?.throwIfAborted(); } finally { await unlink(raw).catch(() => undefined); }
    }
    return undefined;
}

/** Extract an explicitly chosen frame from an identity-bound, private source; failure never changes its media state. */
export async function extractVideoCoverFrame(options: { inputPath: string; workDirectory: string; timeSeconds: number; signal?: AbortSignal }) {
    const { inputPath, workDirectory, timeSeconds, signal } = options;
    signal?.throwIfAborted();
    if (!isAbsolute(inputPath) || !isAbsolute(workDirectory) || !Number.isFinite(timeSeconds) || timeSeconds < 0) throw new VideoProcessingError('invalid_source');
    if (activeProcesses) throw new VideoProcessingError('processor_busy');
    activeProcesses += 1;
    const raw = join(workDirectory, 'selected-frame-raw.jpg'), target = join(workDirectory, 'selected-frame.jpg');
    try {
        const source = await inspect(inputPath, signal);
        if (timeSeconds >= source.durationSeconds) throw new VideoProcessingError('invalid_source');
        await runVideoProcess(binary('ffmpeg'), ['-hide_banner', '-nostdin', '-loglevel', 'error', '-max_alloc', '33554432',
            '-max_pixels', String(maximumPixels), '-threads', '1', ...inputOptions, '-ss', String(timeSeconds), '-f', 'mov', '-i', inputPath,
            '-map', `0:${source.video.index}`, '-frames:v', '1', '-an', '-sn', '-dn', '-map_metadata', '-1',
            '-vf', 'scale=1280:1280:force_original_aspect_ratio=decrease', '-threads', '1', '-q:v', '3', '-fs', String(8 * 1024 ** 2), '-y', raw], { signal, timeoutMs: 30_000 });
        await scheduleCoverArtVariant('video-processing', signal, () => sharp(raw, { failOn: 'error', limitInputPixels: 1280 ** 2 })
            .rotate().resize({ width: 1280, height: 1280, fit: 'inside', withoutEnlargement: true }).jpeg({ quality: 88 }).timeout({ seconds: 10 }).toFile(target));
        return { path: target, contentType: 'image/jpeg' as const };
    } finally { activeProcesses -= 1; await unlink(raw).catch(() => undefined); }
}

/** Prepare one private original; the caller owns the directory and durable object/lease lifecycle. */
export async function processVideoSource(options: { inputPath: string; workDirectory: string; signal?: AbortSignal;
    onProgress?: (event: VideoProcessingProgress) => void }): Promise<ProcessedVideoSource> {
    const { inputPath, workDirectory, signal, onProgress } = options;
    signal?.throwIfAborted();
    if (!isAbsolute(inputPath) || !isAbsolute(workDirectory)) throw new VideoProcessingError('invalid_source');
    if (activeProcesses) throw new VideoProcessingError('processor_busy');
    activeProcesses += 1;
    try {
        onProgress?.({ stage: 'inspect', progress: null });
        const source = await inspect(inputPath, signal);
        onProgress?.({ stage: 'validate', progress: 0, plan: source.plan });
        await decode(inputPath, source, signal, onProgress);
        let outputPath = inputPath;
        if (source.plan !== 'direct') {
            onProgress?.({ stage: 'adapt', progress: 0 }); outputPath = join(workDirectory, 'video-playback.mp4');
            const encoder = process.env.VIDEO_H264_ENCODER || 'libx264';
            if (!['libx264', 'h264_videotoolbox'].includes(encoder)) throw new VideoProcessingError('processor_unavailable');
            const videoCodec = source.videoCompatible ? ['-c:v', 'copy'] : ['-c:v', encoder, ...(encoder === 'libx264'
                ? ['-preset', 'medium', '-crf', '18'] : ['-q:v', '65']), '-pix_fmt', 'yuv420p'];
            const codec = [...videoCodec, ...(source.audio ? source.audio.codec_name === 'aac' ? ['-c:a', 'copy'] : ['-c:a', 'aac', '-b:a', '256k'] : [])];
            await runVideoProcess(binary('ffmpeg'), ['-hide_banner', '-nostdin', '-loglevel', 'error', '-nostats', '-xerror', ...resourceOptions,
                ...inputOptions, '-f', 'mov', '-i', inputPath, '-map', `0:${source.video.index}`, ...(source.audio ? ['-map', `0:${source.audio.index}`] : []),
                ...codec, '-sn', '-dn', '-map_metadata', '-1', '-map_metadata:s', '-1', '-map_chapters', '-1',
                ...(source.videoCompatible && source.video.codec_name === 'hevc' ? ['-tag:v', 'hvc1'] : []),
                '-movflags', '+faststart', '-threads', '2', '-progress', 'pipe:1', '-stats_period', '1', '-fs', String(1024 ** 3), '-y', outputPath], {
                signal, failureCode: 'processing_failed', onLine(line) { if (/^out_time_us=\d{1,15}$/.test(line)) onProgress?.({ stage: 'adapt', progress: Math.min(99, Math.floor(Number(line.slice(12)) / 1_000_000 / source.durationSeconds * 100)) }); }
            });
            const output = await inspect(outputPath, signal);
            if (Math.abs(output.durationSeconds - source.durationSeconds) > .5 || output.probe.streams.length !== 1 + Number(Boolean(source.audio))
                || !output.videoCompatible || output.audio && output.audio.codec_name !== 'aac'
                || output.video.codec_name === 'hevc' && output.video.codec_tag_string !== 'hvc1') throw new VideoProcessingError('processing_failed');
            // Output validation is another full decode; expose its own measured work instead of a stalled adaptation bar.
            onProgress?.({ stage: 'validate', progress: 0 });
            await decode(outputPath, output, signal, onProgress);
        }
        onProgress?.({ stage: 'cover', progress: null });
        const image = await cover(inputPath, source, workDirectory, signal), metadata = await inspect(outputPath, signal);
        const file = await stat(outputPath);
        if (file.size < 1 || file.size > 1024 ** 3) throw new VideoProcessingError('processing_failed');
        return { plan: source.plan, outputPath, contentType: 'video/mp4', byteLength: file.size, durationSeconds: metadata.durationSeconds,
            width: metadata.video.width!, height: metadata.video.height!, videoCodec: metadata.video.codec_name, audioCodec: metadata.audio?.codec_name ?? null,
            ...(image ? { cover: image } : {}) };
    } finally { activeProcesses -= 1; }
}
